css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 6px 12px; margin-bottom: 7px;}
.mz .recuerda-titulo{font-size: 12.5px; font-weight: 700; margin-bottom: 3px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-idea{font-size: 12px; margin-bottom: 3px; line-height: 1.3;}
.mz .recuerda-figuras{display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin-top: 4px;}
.mz .rf-caja{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 4px; text-align: center; display: flex; flex-direction: column; align-items: center; gap: 2px;}
.mz .rf-svg{width: 70px; height: 32px;}
.mz .rf-nombre{font-size: 11.5px; font-weight: 700;}
.mz .rf-info{font-family: sans-serif; font-size: 9px; color: #555; line-height: 1.15;}
.mz .unir-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 6px 40px; align-items: center;}
.mz .unir-col{display: flex; flex-direction: column; gap: 6px; align-items: center; width: 100%;}
.mz .unir-fig{display: flex; align-items: center; justify-content: center; min-height: 40px; width: 100%;}
.mz .unir-fig svg{width: 90px; height: 36px;}
.mz .unir-nom{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 7px 8px; text-align: center; font-size: 13px; font-weight: 700; width: 100%;}
.mz .rodear-mosaico{display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px;}
.mz .rodear-fig{border: 1.5px dashed #000; border-radius: 8px; padding: 4px; display: flex; align-items: center; justify-content: center; min-height: 48px;}
.mz .rodear-fig svg{width: 85px; height: 38px;}
.mz .ac-grid{display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px;}
.mz .ac-caja{display: flex; flex-direction: column; align-items: center; gap: 4px;}
.mz .ac-svg{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 4px; width: 100%; display: flex; align-items: center; justify-content: center; min-height: 56px;}
.mz .ac-svg svg{width: 65px; height: 50px;}
.mz .ac-hueco{width: 32px; height: 24px; border: 1.5px solid var(--bosque); border-radius: 5px;}
.mz .dibujar-grid{display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px;}
.mz .dibujar-caja{display: flex; flex-direction: column; align-items: center; gap: 4px;}
.mz .dibujar-titulo{font-size: 11.5px; font-weight: 700; text-align: center;}
.mz .dibujar-hueco{width: 100%; height: 70px; border: 1.5px solid var(--bosque); border-radius: 8px;}
